var e=[{id:`n_1`,type:`scene_change`,speaker:null,text:null,stage:{bg:`LIFETIME`,bg_animation:null,bgm:`CUTSCENE_HOPE`,filter:`NCFT_NORMAL`,slots:{L:null,C:null,R:null}}},{id:`n_2`,type:`dialog`,speaker:`SPEAR_PERSONA_NULL_NULL`,text:{KOREA:`주인님이든, 사장님이든 호칭 같은 건 아무래도 좋다고. 중요한 건 평생 네 곁에 있겠다는 마음가짐이니까. 으윽… 오글거려. 잘도 이런 말을… 아무튼! 약속한 거야! 약! 속!`,JPN:`ご主人様でも社長でも、呼び方なんてどうでもいいの。大事なのは、一生あんたのそばにいるっていう心なんだから。うう……鳥肌立ったわ。よくもこんな話を……とにかく！　約束よ！　や・く・そ・く！`,ENG:`Master or Boss, the title doesn't really matter. What's important is that I'll be by your side forever. Ngh... I'm getting goosebumps just saying that out loud... Anyway! It's a promise! Got that?`,TWN:`無論是主人或老闆，稱呼一點不重要。重要的是會一直陪伴在你身邊的決心。噁噁…好肉麻。總之！這是我對你的承諾！打勾勾！`},stage:{bg:`LIFETIME`,bg_animation:null,bgm:`CUTSCENE_HOPE`,filter:`NCFT_NORMAL`,slots:{L:null,C:{char_id:`SPEAR_PERSONA_NULL_NULL`,face:`UNIT_LAUGH`,hologram:!1},R:null}}}];export{e as default};